using System;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using ECOLearning.Models;
using ECOLearning.Services;
class ChatIntegration {
 static int checks;
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS: "+name);checks++;}
 static int Main(){using(var db=new QL_HETHONG_CUNGCAP_KHOAHOCEntities1())using(var tx=db.Database.BeginTransaction())try{
  var ticket = new System.Web.Security.FormsAuthenticationTicket(1,"chat@test.invalid",DateTime.Now,DateTime.Now.AddMinutes(10),false,"");
  var cookie = System.Web.Security.FormsAuthentication.Encrypt(ticket);
  Check(ECOLearning.Startup.ChatIdentity(cookie).Identity.Name=="chat@test.invalid","chat accepts encrypted login cookie without MVC Forms auth mode");
  Check(ECOLearning.Startup.ChatIdentity("forged-user-123")==null,"chat rejects forged identity cookie");
  Check(ECOLearning.Startup.ChatIdentity(null)==null,"chat rejects missing login cookie");
  var expired = new System.Web.Security.FormsAuthenticationTicket(1,"chat@test.invalid",DateTime.Now.AddHours(-2),DateTime.Now.AddHours(-1),false,"");
  Check(ECOLearning.Startup.ChatIdentity(System.Web.Security.FormsAuthentication.Encrypt(expired))==null,"chat rejects expired login cookie");
  var sql=File.ReadAllText("Database/Migrations/024_Chat_HoiThoai_TinNhan.sql");
  sql=Regex.Replace(sql,@"^USE .*;$","",RegexOptions.Multiline);
  foreach(var batch in Regex.Split(sql,@"^GO\s*$",RegexOptions.Multiline|RegexOptions.IgnoreCase))if(!string.IsNullOrWhiteSpace(batch))db.Database.ExecuteSqlCommand(batch);
  var key="CT"+Guid.NewGuid().ToString("N").Substring(0,10);
  var teacher=new NguoiDung{hoTen="Chat test teacher",email=key+"t@test.invalid",matKhau="fixture",vaiTro="GiaoVien",trangThai=true};
  var enrolledTeacher=new NguoiDung{hoTen="Chat enrolled teacher",email=key+"et@test.invalid",matKhau="fixture",vaiTro="GiaoVien",trangThai=true};
  var otherTeacher=new NguoiDung{hoTen="Chat other teacher",email=key+"ot@test.invalid",matKhau="fixture",vaiTro="GiaoVien",trangThai=true};
  var learner=new NguoiDung{hoTen="Chat test learner",email=key+"s@test.invalid",matKhau="fixture",vaiTro="HocVien",trangThai=true};
  var other=new NguoiDung{hoTen="Chat outsider",email=key+"o@test.invalid",matKhau="fixture",vaiTro="HocVien",trangThai=true};
  db.NguoiDung.Add(teacher);db.NguoiDung.Add(enrolledTeacher);db.NguoiDung.Add(otherTeacher);db.NguoiDung.Add(learner);db.NguoiDung.Add(other);db.SaveChanges();
  db.KhoaHoc.Add(new KhoaHoc{maKhoaHoc=key,tenKhoaHoc="Chat fixture",maGiaoVien=teacher.maNguoiDung,maDanhMuc=db.DanhMuc.First().maDanhMuc,giaBan=0,trangThai="Đã xuất bản"});db.SaveChanges();
  db.DangKyKhoaHoc.Add(new DangKyKhoaHoc{maDangKy=key,maKhoaHoc=key,maHocVien=learner.maNguoiDung,ngayDangKy=DateTime.Now});db.SaveChanges();
  var svc=new ChatService(db);
  Check(svc.TimHoacMoHoiThoai(key,other.maNguoiDung)==null,"unenrolled learner cannot open chat");
  var room=svc.TimHoacMoHoiThoai(key,learner.maNguoiDung);Check(room!=null,"enrolled learner opens chat");
  Check(svc.TimHoacMoHoiThoai(key,learner.maNguoiDung).MaHoiThoai==room.MaHoiThoai,"reopen uses existing conversation");
  Check(!svc.GuiTinNhan(room.MaHoiThoai,teacher.maNguoiDung,"hello").Success,"teacher cannot message first");
  var otherCourse=key+"B";
  db.KhoaHoc.Add(new KhoaHoc{maKhoaHoc=otherCourse,tenKhoaHoc="Chat course for enrolled teacher",maGiaoVien=otherTeacher.maNguoiDung,maDanhMuc=db.DanhMuc.First().maDanhMuc,giaBan=0,trangThai="Đã xuất bản"});db.SaveChanges();
  db.DangKyKhoaHoc.Add(new DangKyKhoaHoc{maDangKy=otherCourse,maKhoaHoc=otherCourse,maHocVien=enrolledTeacher.maNguoiDung,ngayDangKy=DateTime.Now});db.SaveChanges();
  var enrolledTeacherRoom=svc.TimHoacMoHoiThoai(otherCourse,enrolledTeacher.maNguoiDung);
  Check(enrolledTeacherRoom!=null&&enrolledTeacherRoom.MaHocVien==enrolledTeacher.maNguoiDung,"teacher account can open chat as enrolled learner in another teacher's course");
  Check(svc.GuiTinNhan(enrolledTeacherRoom.MaHoiThoai,enrolledTeacher.maNguoiDung,"Question from enrolled teacher").Success,"teacher account can message first when it is the learner in that course");
  Check(svc.GuiTinNhan(enrolledTeacherRoom.MaHoiThoai,otherTeacher.maNguoiDung,"Answer for enrolled teacher").Success,"course owner can reply to enrolled teacher");
  Check(svc.DemTongTinChuaDoc(enrolledTeacher.maNguoiDung)==1,"unread count uses conversation role for teacher account enrolled elsewhere");
  var sent=svc.GuiTinNhan(room.MaHoiThoai,learner.maNguoiDung,"Question");Check(sent.Success,"learner sends first message");
  Check(svc.GuiTinNhan(room.MaHoiThoai,teacher.maNguoiDung,"Answer").Success,"teacher replies");
  Check(svc.LayDanhSachHoiThoaiHocVien(learner.maNguoiDung).Single(c=>c.MaHoiThoai==room.MaHoiThoai).SoTinChuaDoc==1,"teacher reply produces one unread course message");
  Check(svc.DemTongTinChuaDoc(learner.maNguoiDung,false)==1,"checking course unread count does not mark messages read");
  Check(svc.LayChiTietHoiThoai(room.MaHoiThoai,other.maNguoiDung)==null,"outsider cannot read room");
  Check(svc.LayLichSuTinNhan(room.MaHoiThoai,other.maNguoiDung).Count==0,"outsider cannot read history");
  Check(!svc.GuiTinNhan(room.MaHoiThoai,other.maNguoiDung,"attack").Success,"outsider cannot send");
  Check(!svc.BaoCaoHoiThoai(room.MaHoiThoai,other.maNguoiDung,"attack"),"outsider cannot block room by reporting");
  Check(!svc.ThuHoiTinNhan(sent.TinNhan.MaTinNhan,other.maNguoiDung,room.MaHoiThoai),"outsider cannot recall message");
  Check(!svc.ThuHoiTinNhan(sent.TinNhan.MaTinNhan,learner.maNguoiDung,room.MaHoiThoai+1),"recall cannot target another room");
  Check(svc.ThuHoiTinNhan(sent.TinNhan.MaTinNhan,learner.maNguoiDung,room.MaHoiThoai),"sender recalls own message");
  Check(svc.LayLichSuTinNhan(room.MaHoiThoai,teacher.maNguoiDung).First().DaThuHoi,"history preserves recalled status");
  svc.DanhDauDaDoc(room.MaHoiThoai,learner.maNguoiDung);
  Check(svc.DemTongTinChuaDoc(learner.maNguoiDung,false)==0,"mark read clears unread count");
  Check(svc.GuiTinNhan(room.MaHoiThoai,learner.maNguoiDung,"😊 ❤️ 👍").Success,"emoji persists as Unicode message");
  var imageName=Guid.NewGuid().ToString("N")+".jpg";
  Check(ChatService.TenAnh("[eco-image:../../Web.config]")==null,"image marker rejects path traversal");
  Check(!svc.GuiTinNhan(room.MaHoiThoai,learner.maNguoiDung,"[eco-image:"+imageName+"]").Success,"text sender cannot forge image attachment");
  Check(!svc.GuiAnh(room.MaHoiThoai,other.maNguoiDung,imageName).Success,"outsider cannot send image");
  var image=svc.GuiAnh(room.MaHoiThoai,learner.maNguoiDung,imageName);
  Check(image.Success&&image.TinNhan.ImageUrl=="/Chat/Image/"+image.TinNhan.MaTinNhan,"image uses private message endpoint");
  Check(svc.LayLichSuTinNhan(room.MaHoiThoai,teacher.maNguoiDung).Last().ImageUrl==image.TinNhan.ImageUrl,"image survives history reload");
  Check(svc.LayDanhSachHoiThoaiGiaoVien(teacher.maNguoiDung).Single(c=>c.MaHoiThoai==room.MaHoiThoai).TinCuoiTomTat=="Đã gửi một ảnh","image preview does not expose storage marker");
  Check(svc.ThuHoiTinNhan(image.TinNhan.MaTinNhan,learner.maNguoiDung,room.MaHoiThoai),"sender recalls image");
  Check(svc.LayLichSuTinNhan(room.MaHoiThoai,teacher.maNguoiDung).Last().ImageUrl==null,"recalled image is not exposed in history");
  var expiredMessage=svc.GuiTinNhan(room.MaHoiThoai,learner.maNguoiDung,"Expiry check");
  db.Database.ExecuteSqlCommand("UPDATE dbo.TinNhan SET ngayGui=DATEADD(MINUTE,-6,GETDATE()) WHERE maTinNhan=@p0",expiredMessage.TinNhan.MaTinNhan);
  var expiredItem=svc.LayLichSuTinNhan(room.MaHoiThoai,learner.maNguoiDung).Single(m=>m.MaTinNhan==expiredMessage.TinNhan.MaTinNhan);
  Check(expiredItem.RecallSeconds==0&&!expiredItem.CoTheThuHoi,"expired message has no recall action after reload");
  Check(!svc.ThuHoiTinNhan(expiredItem.MaTinNhan,learner.maNguoiDung,room.MaHoiThoai),"server rejects recall after five minutes");
  Console.WriteLine(checks+" chat checks passed; fixture rolled back.");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{tx.Rollback();}}}
